import { withTenantContext } from '@interdomestik/database';
import { notifications, user } from '@interdomestik/database/schema';
import { and, eq } from 'drizzle-orm';

// Internal claim-status change path: tenantId comes from the validated status-changing session.
// The supplied notification id remains freshly generated by the existing notifier.
export async function storeClaimStatusNotification(input: {
  tenantId: string;
  userId: string;
  notificationId: string;
  claimId: string;
  content: string;
}): Promise<{ success: true; verifiedEmail: string | null } | { success: false; error: string }> {
  if (!input.tenantId?.trim())
    return { success: false, error: 'Missing tenantId for notification' };
  try {
    return await withTenantContext({ tenantId: input.tenantId }, async tx => {
      const recipient = await tx.query.user.findFirst({
        where: and(eq(user.id, input.userId), eq(user.tenantId, input.tenantId)),
        columns: { tenantId: true, email: true, emailVerified: true },
      });
      if (!recipient || recipient.tenantId !== input.tenantId) {
        return { success: false as const, error: 'Recipient unavailable in notification tenant' };
      }
      await tx.insert(notifications).values({
        id: input.notificationId,
        tenantId: input.tenantId,
        userId: input.userId,
        type: 'claim_status_changed',
        title: 'Claim Status Updated',
        content: input.content,
        actionUrl: `/member/claims/${input.claimId}`,
        isRead: false,
      });
      return {
        success: true as const,
        verifiedEmail: recipient.email && recipient.emailVerified ? recipient.email : null,
      };
    });
  } catch (error) {
    console.error('Failed to create in-app notification [claim_status_changed]:', error);
    return { success: false, error: 'Database error' };
  }
}
